using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class MMBatchArchipelagoState20261001{
 static string P(Transform t){string s=t.name;while(t.parent){t=t.parent;s=t.name+"/"+s;}return s;}
 public static void Run(){var s=EditorSceneManager.OpenScene("Assets/Scenes/World/Enroth.unity",OpenSceneMode.Single);var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var rows=new List<string>();
  foreach(var name in new[]{"Archipelago of the Ancients West - LINKED EXTENSION","Archipelago of the Ancients East - LINKED EXTENSION"}){var p=all.First(t=>t.name==name);var t=p.GetComponentInChildren<Terrain>(true);rows.Add($"PARENT|{P(p)}|pos={p.position}|children={p.childCount}");rows.Add($"TERRAIN|{t.name}|pos={t.transform.position}|asset={AssetDatabase.GetAssetPath(t.terrainData)}|size={t.terrainData.size}|layers={t.terrainData.alphamapLayers}");foreach(Transform c in p){var rs=c.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rs.Length==0){rows.Add($"CHILD|{c.name}|children={c.childCount}|renderers=0|pos={c.position}");continue;}var b=rs[0].bounds;for(int i=1;i<rs.Length;i++)b.Encapsulate(rs[i].bounds);rows.Add($"CHILD|{c.name}|children={c.childCount}|renderers={rs.Length}|bounds={b}|pos={c.position}");}}
  var waters=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name.IndexOf("water",StringComparison.OrdinalIgnoreCase)>=0||r.transform.parent&&r.transform.parent.name.IndexOf("water",StringComparison.OrdinalIgnoreCase)>=0).ToArray();rows.Add("WATERS="+waters.Length);foreach(var r in waters.Take(30))rows.Add($"WATER|{P(r.transform)}|bounds={r.bounds}|mat={string.Join(",",r.sharedMaterials.Where(m=>m).Select(m=>m.name))}");
  Directory.CreateDirectory("Validation/EdgeGrid20260923/ArchipelagoExpansion20261001");File.WriteAllLines("Validation/EdgeGrid20260923/ArchipelagoExpansion20261001/state.txt",rows);Debug.Log("ARCHIPELAGO_STATE_DONE");}}
